insert into public.kur_beban (rombel_id,mapel_id,ptk_id,jp)
select r.id,mp2.id,p.id,v.jp from v join mp on mp.c=v.m join gu on gu.c=v.g join public.rombel r on r.nama=v.r and r.jenis_rombel='Kelas Utama' and r.semester_id='20261' join public.kur_mapel mp2 on mp2.nama=mp.n join public.ptk p on lower(p.nama)=gu.n
on conflict (rombel_id,mapel_id,ptk_id) do update set jp=excluded.jp;
select count(*) from public.kur_beban;